{
  "lesson_summary": "Today's lesson plans to teach children to count backwards from 9 to 0. It explains that when counting backwards, every next number is one less than the previous one. The lesson uses the example of Bunty on a hopscotch to illustrate counting one step down and then applies this concept to finding remaining quantities when items are removed, such as pigeons flying away from a roof.",
  "lesson_summary_short": "Today's lesson plans to teach children to count backwards from 9 to 0, saying one less at every step.",
  "checks_summary": "This quiz checks whether the class can count backwards from 9 to 0, identify that each step is one less, and apply this skill to find remaining quantities.",
  "questions": [
    {
      "slo_id": "S1",
      "level": "recall",
      "question": "What is one less than 9?",
      "options": [
        "8",
        "10",
        "9"
      ],
      "correct_index": 0,
      "explanation": "One less than 9 means taking away 1 from 9, which gives 8.",
      "selected_because": "First step of the worked example, identifying one less than 9.",
      "distractor_misconceptions": {
        "1": "Confuses 'one less' with 'one more' or forward counting.",
        "2": "Repeats the same number instead of changing it."
      },
      "option_feedback": {
        "correct": "Yes, 8 is one less than 9. This is the first step when counting backwards from 9.",
        "wrong": {
          "1": "When counting backwards, we say one less, not one more. One less than 9 is 8.",
          "2": "When counting backwards, the number changes. One less than 9 is 8."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "One less than 9 is 8 — write 8",
      "teaching_error": null
    },
    {
      "slo_id": "S2",
      "level": "understand",
      "question": "What happens when counting backwards?",
      "options": [
        "The next number is one more.",
        "The next number is one less.",
        "The number stays the same."
      ],
      "correct_index": 1,
      "explanation": "When counting backwards, each subsequent number in the sequence is always one less than the previous one.",
      "selected_because": "Key fact of the lesson about the nature of counting backwards.",
      "distractor_misconceptions": {
        "0": "Confuses counting backwards with counting forwards.",
        "2": "Believes the number does not change when counting backwards."
      },
      "option_feedback": {
        "correct": "That's right! When counting backwards, every next number is one less.",
        "wrong": {
          "0": "When counting backwards, we go down, not up. The next number is one less.",
          "2": "The numbers change when you count backwards. The next number is one less."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "When we count backwards, every next number is one less: 9, 8, 7, 6, 5, 4, 3, 2, 1, 0.",
      "teaching_error": null
