      "correct_index": 0,
      "explanation": "Counting backwards means starting from a higher number and decreasing by one at each step, like 9, 8, 7.",
      "selected_because": "Identifying a correct sequence of counting backwards.",
      "distractor_misconceptions": {
        "1": "Confuses counting backwards with counting forwards.",
        "2": "Repeats a number or skips numbers when counting."
      },
      "option_feedback": {
        "correct": "Excellent! The sequence 9, 8, 7 shows counting backwards correctly.",
        "wrong": {
          "1": "This sequence is counting forwards. Counting backwards goes 9, 8, 7.",
          "2": "In this sequence, a number is repeated or skipped. Counting backwards goes 9, 8, 7."
        }
      },
      "figure": null,
      "figure_role": null,
      "source_quote": "The full backwards run: 9, 8, 7, 6, 5, 4, 3, 2, 1, 0.",
